Lemma ru_M : forall regs m (DW k : Z),
  (1 <= DW < 2 ^ 31)%Z -> k = (DW mod 32)%Z -> (0 <= k < 32)%Z ->
  (forall j, (1 <= j <= 31)%Z -> exists (bs : list byte) (v : word), rdn SEGS m (Z_to_bv 64 (0x1f424 + 4 * j)) 4 = Some bs /\ bytes_le_to_Z bs = bv_unsigned v) ->
  getr regs 18 = Z_to_bv 64 DW ->
  exists regs',
    msteps SEGS (mkst regs (0x79bd4 : word) m rom) (mkst regs' (0x79d08 : word) m rom)
    /\ getr regs' 20 = Z_to_bv 64 k
