(* [comment removed for export] *)
Definition pcG_l1s (set : bool) : word := if set then 0x79c40 else 0x79b84.   (* [comment removed for export] *)
Definition pcG_l1 (set : bool) : word := if set then 0x79c48 else 0x79b90.    (* [comment removed for export] *)
Definition pcG_l1x (set : bool) : word := if set then 0x79c60 else 0x79ba8.   (* [comment removed for export] *)
Definition pcG_l2 (set : bool) : word := if set then 0x79f64 else 0x79f98.    (* [comment removed for export] *)
Definition pcG_l2r (set : bool) : word := if set then 0x79f78 else 0x79fac.   (* [comment removed for export] *)
Definition pcG_l3t (set : bool) : word := if set then 0x79c68 else 0x79bac.   (* [comment removed for export] *)
Definition pcG_l3 (set : bool) : word := if set then 0x79c6c else 0x79bb8.    (* [comment removed for export] *)

(* [comment removed for export] *)
Lemma ru_G1d : forall (set : bool) regs m (a6 DW op : Z),
  (1 <= a6 < 32)%Z -> (1 <= DW)%Z -> (DW < 32 - a6)%Z -> op = (if set then 15 else 0)%Z ->
  (forall j, (1 <= j <= 31)%Z -> exists (bs : list byte) (v : word), rdn SEGS m (Z_to_bv 64 (0x1f424 + 4 * j)) 4 = Some bs /\ bytes_le_to_Z bs = bv_unsigned v) ->
  getr regs 16 = Z_to_bv 64 a6 -> getr regs 18 = Z_to_bv 64 DW -> getr regs 11 = Z_to_bv 64 op ->
  exists regs',
    msteps SEGS (mkst regs (0x79b40 : word) m rom) (mkst regs' (pcG_l1s set) m rom)
    /\ getr regs' 13 = Z_to_bv 64 1 /\ getr regs' 23 = Z_to_bv 64 1 /\ getr regs' 22 = Z_to_bv 64 0
